package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen0Test {

    @Test
    public void testEbeMultiply_StandardCase() {
        // Setup a sparse vector: [1.0, 0.0, 3.0, 0.0, 5.0]
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(0, 1.0);
        vector.setEntry(2, 3.0);
        vector.setEntry(4, 5.0);

        // Multiplier array: [2.0, 10.0, 4.0, 10.0, 6.0]
        double[] multiplier = {2.0, 10.0, 4.0, 10.0, 6.0};

        // Expected result: [1.0*2.0, 0.0, 3.0*4.0, 0.0, 5.0*6.0] -> [2.0, 0.0, 12.0, 0.0, 30.0]
        OpenMapRealVector result = vector.ebeMultiply(multiplier);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(2.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(12.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(3), 1e-10);
        Assert.assertEquals(30.0, result.getEntry(4), 1e-10);
    }

    @Test
    public void testEbeMultiply_EmptyVector() {
        // Setup an empty sparse vector
        OpenMapRealVector vector = new OpenMapRealVector(3);
        double[] multiplier = {1.0, 2.0, 3.0};

        OpenMapRealVector result = vector.ebeMultiply(multiplier);

        Assert.assertEquals(3, result.getDimension());
        // Since original vector had no entries, result should have no entries (all zero)
        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
    }

    @Test
    public void testEbeMultiply_ZeroMultiplier() {
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 10.0);
        vector.setEntry(1, 20.0);

        double[] multiplier = {0.0, 0.0};
        OpenMapRealVector result = vector.ebeMultiply(multiplier);

        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiply_DimensionMismatch() {
        // Vector dimension is 3
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 1.0);

        // Multiplier dimension is 2
        double[] multiplier = {1.0, 2.0};

        // Should throw DimensionMismatchException via checkVectorDimensions
        vector.ebeMultiply(multiplier);
    }

    @Test
    public void testEbeMultiply_Immutability() {
        // Ensure the original vector is not modified
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 5.0);
        vector.setEntry(1, 10.0);

        double[] multiplier = {2.0, 2.0};
        OpenMapRealVector result = vector.ebeMultiply(multiplier);

        // Check result
        Assert.assertEquals(10.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(20.0, result.getEntry(1), 1e-10);

        // Check original remains unchanged
        Assert.assertEquals(5.0, vector.getEntry(0), 1e-10);
        Assert.assertEquals(10.0, vector.getEntry(1), 1e-10);
    }

    @Test
    public void testEbeMultiply_LargeIndices() {
        // Test sparsity handling with large dimension
        int dim = 1000;
        OpenMapRealVector vector = new OpenMapRealVector(dim);
        vector.setEntry(999, 2.0);

        double[] multiplier = new double[dim];
        multiplier[999] = 5.0;

        OpenMapRealVector result = vector.ebeMultiply(multiplier);

        Assert.assertEquals(10.0, result.getEntry(999), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
    }
}
